    mff328011b804: "The network connection is abnormal. The task status is being confirmed. Please check the results later.",
    m47251f2c6902: "The sum of the reference video duration and the output video duration cannot exceed 30 seconds; when no reference video is provided, the maximum output is 30 seconds.",
    m67c79e7ff44f: "The output video duration cannot exceed 30 seconds; when no reference video is provided, the maximum output time is 30 seconds.",
    m5ace786bd54e: "The length of the reference video exceeds the limit: the current channel supports a maximum of {value1} seconds. Please crop the reference video and try again.",
    m1b9129a8d05c: "Reference audio duration exceeds the limit: the current channel supports a maximum of {value1} seconds. Please cut the audio and try again.",
    mfc6a047147d5: "The reference video resolution is too high: The current channel requires that the number of pixels in a single frame does not exceed {value1}. Please compress the reference video resolution and try again.",
    m8c9f8eed1d02: "The reference audio format is not supported by the current channel, please use common MP3 or WAV and try again.",
